import {Farm,starter,connectExample,TYPES,DIRS,ports,line,key,COLS,ROWS} from './engine.js';
const canvas=document.querySelector('#farm'),ctx=canvas.getContext('2d');
let farm=starter(),tool='belt',direction=0,hover=null,drag=null,pan=null,selected=null,paused=false,speed=1,last=0,history=[];
const view={x:0,y:0,tile:30,width:0,height:0};
const $=s=>document.querySelector(s),arrows=['→','↓','←','↑'],names=['EAST','SOUTH','WEST','NORTH'];
const colors={wheat:'#f3c957',flour:'#ece5c9',bread:'#d48649'};
function message(s){$('#message').textContent=s;}
function checkpoint(){history.push(farm.snapshot());if(history.length>40)history.shift();$('#undo').disabled=false;}
function setTool(t){tool=t;selected=null;drag=null;for(const b of document.querySelectorAll('[data-tool]')){b.classList.toggle('selected',b.dataset.tool===t);b.setAttribute('aria-pressed',b.dataset.tool===t);}report();}
function rotate(){direction=(direction+1)%4;$('#direction').textContent=`${names[direction]} ${arrows[direction]}`;}
function report(){const b=farm.buildings.find(b=>b.id===selected);if(b){const t=TYPES[b.type];$('#inspect-title').textContent=t.name;$('#inspect-description').textContent=b.type==='house'?'Bread delivered here feeds the pigs. This first prototype tracks deliveries without growing demand.':b.type==='field'?'Produces 1 wheat every 3 seconds. Output holds up to 4 wheat.':`Turns ${t.amount} ${t.input} into 1 ${t.out} every ${t.time} seconds.`;$('#inspect-detail').textContent=b.type==='house'?`${farm.stats.bread} loaves delivered`: `${t.input?`Input: ${b.input}/8 ${t.input} · `:''}Output: ${b.output}/4 ${t.out} · ${b.output>=4?'Output blocked':t.input&&b.input<t.amount?'Waiting for '+t.input:'Working'}`;return;}
 const info={belt:['Conveyor','Drag between tiles. Lines snap horizontally or vertically. The drag sets travel direction.'],field:['Wheat field','Place a 3 × 3 field. Wheat leaves through the gold output. Rotate before placing with R.'],mill:['Mill','2 wheat → 1 flour. Feed the blue input; collect flour at the gold output.'],bakery:['Bakery','2 flour → 1 bread. Deliver the bread to the farmhouse’s blue input.'],inspect:['Inspect','Select a building to see its recipe, stored goods, and production status.'],erase:['Remove','Click a building or drag a straight line to remove conveyors. The farmhouse stays in place.']};$('#inspect-title').textContent=info[tool][0];$('#inspect-description').textContent=info[tool][1];$('#inspect-detail').textContent='';}
function resize(){const r=canvas.getBoundingClientRect(),d=window.devicePixelRatio||1;canvas.width=Math.round(r.width*d);canvas.height=Math.round(r.height*d);view.width=r.width;view.height=r.height;ctx.setTransform(d,0,0,d,0,0);if(!last)fit();}
function fit(){view.tile=Math.min((view.width-35)/COLS,(view.height-120)/ROWS,45);view.tile=Math.max(8,view.tile);view.x=(view.width-COLS*view.tile)/2;view.y=(view.height-ROWS*view.tile)/2+30;}
function zoom(factor,cx=view.width/2,cy=view.height/2){const next=Math.min(85,Math.max(8,view.tile*factor)),ratio=next/view.tile;view.x=cx-(cx-view.x)*ratio;view.y=cy-(cy-view.y)*ratio;view.tile=next;}
function point(e){const r=canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};}
function tile(e){const p=point(e);return{x:Math.floor((p.x-view.x)/view.tile),y:Math.floor((p.y-view.y)/view.tile)};}
function drawText(s,x,y,size,color='#eee4bd',align='center',font='sans-serif'){ctx.fillStyle=color;ctx.textAlign=align;ctx.textBaseline='middle';ctx.font=`600 ${size}px ${font}`;ctx.fillText(s,x,y);}
function draw(){const t=view.tile;ctx.clearRect(0,0,view.width,view.height);ctx.fillStyle='#697659';ctx.fillRect(0,0,view.width,view.height);ctx.save();ctx.translate(view.x,view.y);
 // The map is an explicit tile plan, with schematic building footprints and ports.
 for(let y=0;y<ROWS;y++)for(let x=0;x<COLS;x++){ctx.fillStyle=(x+y)%2?'#6c795b':'#707d5e';ctx.fillRect(x*t,y*t,t,t);ctx.strokeStyle='#5b6c5070';ctx.lineWidth=.7;ctx.strokeRect(x*t,y*t,t,t);}
 ctx.strokeStyle='#344f36';ctx.lineWidth=2;ctx.strokeRect(0,0,COLS*t,ROWS*t);
 for(const belt of Object.values(farm.belts)){const x=belt.x*t,y=belt.y*t;ctx.fillStyle='#314037';ctx.fillRect(x+1,y+1,t-2,t-2);ctx.strokeStyle='#c5b36d';ctx.lineWidth=Math.max(1,t*.05);if(belt.dir%2===0){ctx.beginPath();ctx.moveTo(x,y+t*.18);ctx.lineTo(x+t,y+t*.18);ctx.moveTo(x,y+t*.82);ctx.lineTo(x+t,y+t*.82);ctx.stroke();}else{ctx.beginPath();ctx.moveTo(x+t*.18,y);ctx.lineTo(x+t*.18,y+t);ctx.moveTo(x+t*.82,y);ctx.lineTo(x+t*.82,y+t);ctx.stroke();}drawText(arrows[belt.dir],x+t/2,y+t/2,t*.52,'#899780');}
 for(const b of farm.buildings)drawBuilding(b);
 for(const belt of Object.values(farm.belts)){if(!belt.item)continue;const x=(belt.x+.5)*t,y=(belt.y+.5)*t;ctx.fillStyle='#172b28';ctx.fillRect(x-t*.21+2,y-t*.21+2,t*.42,t*.42);ctx.fillStyle=colors[belt.item];ctx.fillRect(x-t*.21,y-t*.21,t*.42,t*.42);ctx.strokeStyle='#fce9b2';ctx.lineWidth=1;ctx.strokeRect(x-t*.21,y-t*.21,t*.42,t*.42);}
 if(hover&&farm.inside(hover.x,hover.y)&&!pan){if(tool==='belt'||tool==='erase'){const cells=drag?line(drag,hover,direction):[{...hover,dir:direction}],valid=tool==='erase'||farm.canLay(cells);for(const c of cells){ctx.fillStyle=valid?(tool==='erase'?'#b5403ea0':'#e4c77690'):'#e0525690';ctx.fillRect(c.x*t+1,c.y*t+1,t-2,t-2);if(tool==='belt')drawText(arrows[c.dir],(c.x+.5)*t,(c.y+.5)*t,t*.6,'#20372b');}if(drag)drawText(`${cells.length} TILES`,(cells.at(-1).x+.5)*t,(cells.at(-1).y-.5)*t,Math.max(11,t*.4),'#fff0c2');}else if(TYPES[tool]){const valid=farm.canPlace(hover.x,hover.y);drawBuilding({type:tool,x:hover.x,y:hover.y,dir:direction,progress:0,input:0,output:0},true);ctx.fillStyle=valid?'#d5df9a25':'#dd2e4277';ctx.fillRect(hover.x*t,hover.y*t,3*t,3*t);ctx.strokeStyle=valid?'#f5dfa2':'#ff9898';ctx.lineWidth=2;ctx.strokeRect(hover.x*t,hover.y*t,3*t,3*t);}else{ctx.strokeStyle='#ffe5a1';ctx.lineWidth=2;ctx.strokeRect(hover.x*t,hover.y*t,t,t);}}
 ctx.restore();}
function drawBuilding(b,ghost=false){const t=view.tile,x=b.x*t,y=b.y*t,def=TYPES[b.type];ctx.save();if(ghost)ctx.globalAlpha=.65;ctx.fillStyle='#25352d77';ctx.fillRect(x+5,y+6,3*t,3*t);ctx.fillStyle=def.color;ctx.fillRect(x+1,y+1,3*t-2,3*t-2);ctx.strokeStyle='#29392d';ctx.lineWidth=2;ctx.strokeRect(x+1,y+1,3*t-2,3*t-2);ctx.strokeStyle='#203d302c';ctx.lineWidth=1;for(let n=1;n<3;n++){ctx.beginPath();ctx.moveTo(x+n*t,y);ctx.lineTo(x+n*t,y+3*t);ctx.moveTo(x,y+n*t);ctx.lineTo(x+3*t,y+n*t);ctx.stroke();}
 ctx.fillStyle='#253b2ce0';ctx.fillRect(x+t*.48,y+t*.55,t*2.04,t*1.8);drawText(b.type==='house'?'★':b.type==='field'?'W':b.type==='mill'?'M':'B',x+t*1.5,y+t*1.26,t*.7,b.type==='house'?'#f6c46e':'#f0ddb0');drawText(b.type==='house'?'FARMHOUSE':b.type.toUpperCase(),x+t*1.5,y+t*1.92,Math.max(7,t*.29),'#e5dfb7');
 if(!ghost&&b.type!=='house'){ctx.fillStyle='#1c322c';ctx.fillRect(x+t*.5,y+2.58*t,t*2,t*.15);ctx.fillStyle='#f1cc6a';ctx.fillRect(x+t*.5,y+2.58*t,t*2*Math.min(1,b.progress/def.time),t*.15);}
 const p=ports(b);for(const role of ['input','output']){if(role==='input'&&!def.input||role==='output'&&!def.out)continue;const pos=p[role];ctx.fillStyle=role==='input'?'#81c0cb':'#f2c763';ctx.fillRect(pos.x*t+1,pos.y*t+1,t-2,t-2);drawText(arrows[b.dir],(pos.x+.5)*t,(pos.y+.5)*t,t*.7,'#233b34');}
 if(b.id===selected){ctx.strokeStyle='#fff0b8';ctx.lineWidth=3;ctx.strokeRect(x-3,y-3,3*t+6,3*t+6);}if(!ghost){const label=b.type==='house'?`${farm.stats.bread} BREAD RECEIVED`:b.output>=4?'OUTPUT FULL':def.input&&b.input<def.amount?`NEEDS ${def.input.toUpperCase()}`:'WORKING';drawText(label,x+1.5*t,y+3.43*t,Math.max(8,t*.29),'#263c2e');}ctx.restore();}
canvas.addEventListener('pointerdown',e=>{if(e.button===2||e.button===1||e.altKey){pan={...point(e),vx:view.x,vy:view.y};canvas.setPointerCapture(e.pointerId);return;}if(e.button!==0)return;canvas.focus({preventScroll:true});hover=tile(e);canvas.setPointerCapture(e.pointerId);if(tool==='belt'||tool==='erase'){drag={...hover};}else if(tool==='inspect'){selected=farm.at(hover.x,hover.y)?.id??null;report();}else if(TYPES[tool]){if(!farm.canPlace(hover.x,hover.y)){message('That 3 × 3 footprint is blocked. Choose nine empty tiles.');return;}checkpoint();farm.place(tool,hover.x,hover.y,direction);message(`${TYPES[tool].name} placed. Connect its marked ports.`);}});
canvas.addEventListener('pointermove',e=>{hover=tile(e);if(pan){const p=point(e);view.x=pan.vx+p.x-pan.x;view.y=pan.vy+p.y-pan.y;}});
canvas.addEventListener('pointerup',e=>{if(pan){pan=null;return;}if(!drag)return;hover=tile(e);const cells=line(drag,hover,direction);drag=null;if(tool==='belt'){if(!farm.canLay(cells)){message('Line blocked: conveyors must stay outside building footprints. End beside the marked port.');return;}checkpoint();farm.lay(cells);direction=cells[0].dir;$('#direction').textContent=`${names[direction]} ${arrows[direction]}`;message(`${cells.length} conveyor tile${cells.length===1?'':'s'} placed, flowing ${names[direction].toLowerCase()}.`);}else if(tool==='erase'){if(!cells.some(c=>farm.belts[key(c.x,c.y)]||(farm.at(c.x,c.y)&&farm.at(c.x,c.y).type!=='house'))){message('Nothing to remove here. The farmhouse stays in place.');return;}checkpoint();farm.remove(cells);message('Removed. Undo restores the previous layout.');}});
canvas.addEventListener('pointercancel',()=>{drag=null;pan=null;});canvas.addEventListener('pointerleave',()=>{if(!drag&&!pan)hover=null;});canvas.addEventListener('contextmenu',e=>e.preventDefault());canvas.addEventListener('wheel',e=>{e.preventDefault();const p=point(e);zoom(e.deltaY<0?1.12:1/1.12,p.x,p.y);},{passive:false});
document.querySelectorAll('[data-tool]').forEach(b=>b.addEventListener('click',()=>setTool(b.dataset.tool)));
$('#rotate').onclick=rotate;$('#pause').onclick=()=>{paused=!paused;$('#pause').textContent=paused?'▶ Resume':'Ⅱ Pause';};$('#speed').onclick=()=>{speed=speed===1?2:speed===2?4:1;$('#speed').textContent=`${speed}×`;};$('#undo').onclick=()=>{if(!history.length)return;farm.restore(history.pop());$('#undo').disabled=!history.length;selected=null;report();message('Previous layout restored.');};$('#reset').onclick=()=>{checkpoint();farm=starter();selected=null;report();message('Starter farm restored. Connect the gold outputs to the blue inputs.');};$('#example').onclick=()=>{const cells=[...line({x:6,y:11},{x:10,y:11}),...line({x:14,y:11},{x:18,y:11}),...line({x:22,y:11},{x:28,y:11})];const matches=['field','mill','bakery','house'].every((type,i)=>farm.at([3,11,19,29][i],10)?.type===type);if(!matches||!farm.canLay(cells)){message('The starter layout has changed. Use Reset first, or connect your buildings manually.');return;}checkpoint();connectExample(farm);message('Example connected. Wheat becomes flour, then bread. Follow the parcels to the house.');};$('#zoom-in').onclick=()=>zoom(1.2);$('#zoom-out').onclick=()=>zoom(1/1.2);$('#fit').onclick=fit;
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey)return;const n=Number(e.key);if(n>=1&&n<=6)setTool(['belt','field','mill','bakery','inspect','erase'][n-1]);if(e.key.toLowerCase()==='r')rotate();if(e.key==='Escape'){drag=null;setTool('inspect');}if(e.code==='Space'&&e.target===canvas){e.preventDefault();$('#pause').click();}if(e.target===canvas&&e.key.startsWith('Arrow')){e.preventDefault();if(e.key==='ArrowLeft')view.x+=40;if(e.key==='ArrowRight')view.x-=40;if(e.key==='ArrowUp')view.y+=40;if(e.key==='ArrowDown')view.y-=40;}if(e.key==='+'||e.key==='=')zoom(1.2);if(e.key==='-')zoom(1/1.2);});
new ResizeObserver(resize).observe(canvas);report();resize();let reportAt=0;
function frame(now){if(last&&!paused)farm.advance(Math.min((now-last)/1000,.1)*speed);last=now;draw();if(now-reportAt>200){$('#wheat').textContent=farm.stats.wheat;$('#flour').textContent=farm.stats.flour;$('#bread').textContent=farm.stats.bread;report();reportAt=now;}requestAnimationFrame(frame);}requestAnimationFrame(frame);
